<!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#132c59"><title>Ráérő</title><link rel="manifest" href="/app.webmanifest"><link rel="apple-touch-icon" href="/pwa/icon-180.png"></head><body><p>Ráérő megnyitása…</p><a href="/belepes">Belépés</a><script>let target='/belepes';try{const provider=localStorage.getItem('raero-app-provider');if(/^[1-9][0-9]{0,8}$/.test(provider||''))target='/?provider='+provider;}catch{}location.replace(target);</script></body></html>
